use std::collections::HashSet;
use std::sync::{Arc, Mutex};
use std::thread;

#[derive(Default)]
struct Registry {
    documents: HashSet<String>,
    count: usize,
}

fn main() {
    let registry = Arc::new(Mutex::new(Registry::default()));
    let mut workers = Vec::new();
    for _ in 0..2 {
        let registry = Arc::clone(&registry);
        workers.push(thread::spawn(move || {
            {
                let mut state = registry.lock().expect("healthy registry");
                if state.documents.insert("main.rs".to_owned()) {
                    state.count += 1;
                }
                assert_eq!(state.count, state.documents.len());
            } // unlock before other work
        }));
    }
    for worker in workers {
        worker.join().expect("worker completed");
    }
    let state = registry.lock().expect("healthy final registry");
    assert_eq!(state.count, 1);
    assert_eq!(state.documents.len(), 1);
    println!("one consistent insertion");
}

use std::sync::RwLock;

struct Settings {
    version: u64,
    title: String,
}

fn commit(state: &RwLock<Settings>, expected: u64, title: String) -> bool {
    let mut current = state.write().expect("healthy settings");
    if current.version != expected {
        return false;
    }
    let Some(next) = current.version.checked_add(1) else {
        return false;
    };
    current.title = title;
    current.version = next;
    true
}

fn main() {
    let state = RwLock::new(Settings {
        version: 0,
        title: "crab".into(),
    });
    let (version, title) = {
        let current = state.read().expect("healthy snapshot");
        (current.version, current.title.clone())
    };
    let proposal = title.to_uppercase(); // no guard is held
    assert!(commit(&state, version, "new edit".into()));
    assert!(!commit(&state, version, proposal));
    assert_eq!(state.read().unwrap().title, "new edit");
    println!("stale proposal rejected");
}

