use std::panic::catch_unwind;
use std::sync::Mutex;

struct Index {
    items: Vec<String>,
    count: usize,
}

fn main() {
    let index = Mutex::new(Index {
        items: Vec::new(),
        count: 0,
    });
    let failed = catch_unwind(|| {
        let mut state = index.lock().unwrap();
        state.items.push("main.rs".into());
        panic!("injected interruption before updating count");
    });
    assert!(failed.is_err());
    assert!(index.is_poisoned());
    {
        let mut state = match index.lock() {
            Ok(_) => panic!("fixture must be poisoned"),
            Err(error) => error.into_inner(),
        };
        state.count = state.items.len();
        index.clear_poison();
    }
    let state = index.lock().expect("repaired index");
    assert_eq!(state.count, 1);
    assert_eq!(state.count, state.items.len());
    println!("derived state repaired before reuse");
}

pub fn count_owned(input: &str) -> usize {
