use serde::Deserialize;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ImportRequest {
    title: String,
    tasks: Vec<String>,
}

#[derive(Debug, PartialEq)]
struct TaskBatch {
    title: String,
    tasks: Vec<String>,
}

fn decode(input: &str) -> Result<TaskBatch, String> {
    if input.len() > 16_384 {
        return Err("input exceeds 16 KiB".into());
    }
    let wire: ImportRequest = serde_json::from_str(input)
        .map_err(|e| format!("JSON at {}:{}: {e}", e.line(), e.column()))?;
    let title = wire.title.trim().to_owned();
    if title.is_empty() || title.chars().count() > 80 {
        return Err("title must contain 1..=80 Unicode scalar values".into());
    }
    if wire.tasks.len() > 100 {
        return Err("at most 100 tasks are accepted".into());
    }
    let mut tasks = Vec::with_capacity(wire.tasks.len());
    for (index, task) in wire.tasks.into_iter().enumerate() {
        let task = task.trim().to_owned();
        if task.is_empty() {
            return Err(format!("tasks[{index}] is empty"));
        }
        tasks.push(task);
    }
    Ok(TaskBatch { title, tasks })
}

fn main() {
    let good = r#"{"title":" Rust lab ","tasks":["read","test"]}"#;
    let batch = decode(good).expect("valid fixture");
    assert_eq!(batch.title, "Rust lab");
    assert_eq!(batch.tasks, ["read", "test"]);
    assert!(decode(r#"{"title":" ","tasks":[]}"#).is_err());
    assert!(decode(r#"{"title":"lab","tasks":[""]}"#).is_err());
    assert!(decode(r#"{"title":"lab","tasks":[],"typo":1}"#).is_err());
    assert!(decode(&" ".repeat(16_385)).is_err());
    println!("validated {} tasks", batch.tasks.len());
}

use serde_json::{Value, json};

fn describe(value: &Value) -> Result<&'static str, &'static str> {
    if !value.is_object() {
        return Err("patch must be an object");
    }
    match value.get("nickname") {
        None => Ok("unchanged"),
        Some(Value::Null) => Ok("clear"),
        Some(Value::String(s)) if s.is_empty() => Ok("empty string"),
        Some(Value::String(_)) => Ok("replace"),
        Some(_) => Err("nickname must be a string or null"),
    }
}

fn main() {
    assert!(describe(&json!(7)).is_err());
    assert_eq!(describe(&json!({})), Ok("unchanged"));
    assert_eq!(describe(&json!({"nickname":null})), Ok("clear"));
    assert_eq!(describe(&json!({"nickname":""})), Ok("empty string"));
    assert_eq!(describe(&json!({"nickname":"crab"})), Ok("replace"));
    assert!(describe(&json!({"nickname":7})).is_err());
    println!("all presence cases checked");
}

