fn checked_total(values: &[u32]) -> Option<u32> {
    values.iter().try_fold(0_u32, |sum, value| sum.checked_add(*value))
}

fn main() {
    assert_eq!(checked_total(&[12, 8, 5]), Some(25));
    assert_eq!(checked_total(&[u32::MAX, 1]), None);
    println!("{} / {} / {}-bit pointers",
