#[derive(Debug, Clone, Copy, PartialEq)]
enum State { Draft, Ready, Sent }
#[derive(Clone, Copy)]
enum Action { Validate, Edit, Send }
fn apply(state: &mut State, action: Action) -> Result<(), &'static str> {
    let next = match (*state, action) {
        (State::Draft, Action::Validate) => State::Ready,
        (State::Ready, Action::Edit) => State::Draft,
        (State::Ready, Action::Send) => State::Sent,
        _ => return Err("action is not allowed in this state"),
    };
    *state = next;
    Ok(())
}
fn main() {
    let mut state = State::Draft;
    assert!(apply(&mut state, Action::Send).is_err());
    assert_eq!(state, State::Draft);
    apply(&mut state, Action::Validate).unwrap();
    apply(&mut state, Action::Edit).unwrap();
    assert_eq!(state, State::Draft);
    apply(&mut state, Action::Validate).unwrap();
    apply(&mut state, Action::Send).unwrap();
    assert_eq!(state, State::Sent);
    assert!(apply(&mut state, Action::Validate).is_err());
    assert_eq!(state, State::Sent);
    println!("Workflow checks passed: {state:?}");
}

