use std::collections::{BTreeMap, BTreeSet};
type Graph<'a> = BTreeMap<&'a str, BTreeSet<&'a str>>;
#[derive(Debug, PartialEq)]
enum PlanError<'a> {
    Unknown { package: &'a str, dependency: &'a str },
    Cycle { blocked: Vec<&'a str>, witness: Vec<&'a str> },
}
fn plan<'a>(graph: &Graph<'a>) -> Result<Vec<&'a str>, PlanError<'a>> {
    let mut remaining_count = BTreeMap::new();
    let mut consumers: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for (&package, dependencies) in graph {
        remaining_count.insert(package, dependencies.len());
        for &dependency in dependencies {
            if !graph.contains_key(dependency) {
                return Err(PlanError::Unknown { package, dependency });
            }
            consumers.entry(dependency).or_default().push(package);
        }
    }
    let mut ready: BTreeSet<&str> = remaining_count.iter()
        .filter_map(|(&name, &count)| (count == 0).then_some(name)).collect();
    let mut order = Vec::new();
    while let Some(package) = ready.pop_first() {
        order.push(package);
        for &consumer in consumers.get(package).into_iter().flatten() {
            let count = remaining_count.get_mut(consumer).unwrap();
            *count -= 1;
            if *count == 0 { ready.insert(consumer); }
        }
    }
    if order.len() == graph.len() { return Ok(order); }
    let blocked: BTreeSet<&str> = remaining_count.iter()
        .filter_map(|(&name, &count)| (count > 0).then_some(name)).collect();
    let mut positions = BTreeMap::new();
    let mut walk = Vec::new();
    let mut current = *blocked.first().unwrap();
    let witness = loop {
        if let Some(&start) = positions.get(current) {
            let mut cycle = walk[start..].to_vec();
            cycle.push(current);
            break cycle;
        }
        positions.insert(current, walk.len());
        walk.push(current);
        current = graph[current].iter().copied()
            .find(|name| blocked.contains(*name)).unwrap();
    };
    Err(PlanError::Cycle { blocked: blocked.into_iter().collect(), witness })
}
fn graph<'a>(rows: &[(&'a str, &[&'a str])]) -> Graph<'a> {
    rows.iter().map(|(name, dependencies)|
        (*name, dependencies.iter().copied().collect())).collect()
}
fn main() {
    let inputs = graph(&[("web", &["core"]), ("cli", &["core"]),
        ("core", &["config"]), ("config", &[])]);
    assert_eq!(plan(&inputs), Ok(vec!["config", "core", "cli", "web"]));
    let cyclic = graph(&[("a", &["b"]), ("b", &["a"]), ("c", &["a"])]);
    assert_eq!(plan(&cyclic), Err(PlanError::Cycle {
        blocked: vec!["a", "b", "c"], witness: vec!["a", "b", "a"] }));
    println!("deterministic plan and cycle witness: ok");
}
#[test]
fn unknown_dependency_is_not_treated_as_a_leaf() {
    assert_eq!(plan(&graph(&[("app", &["missing"])])),
        Err(PlanError::Unknown { package: "app", dependency: "missing" }));
}
#[test]
fn empty_and_duplicate_edge_inputs_have_defined_results() {
    assert_eq!(plan(&Graph::new()), Ok(vec![]));
    assert_eq!(plan(&graph(&[("app", &["core", "core"]), ("core", &[])])),
        Ok(vec!["core", "app"]));
}

use std::sync::atomic::{AtomicU64, Ordering};
static NEXT_ARENA: AtomicU64 = AtomicU64::new(1);

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct Handle { arena: u64, index: usize, generation: u64 }
struct Slot<T> { generation: u64, value: Option<T> }
struct Arena<T> { identity: u64, slots: Vec<Slot<T>>, free: Vec<usize> }
impl<T> Arena<T> {
    fn new() -> Option<Self> {
        let identity = loop {
            let current = NEXT_ARENA.load(Ordering::Relaxed);
            let next = current.checked_add(1)?;
            if NEXT_ARENA.compare_exchange_weak(current, next,
                Ordering::Relaxed, Ordering::Relaxed).is_ok() { break current; }
        };
        Some(Self { identity, slots: Vec::new(), free: Vec::new() })
    }
    fn insert(&mut self, value: T) -> Handle {
        let index = if let Some(index) = self.free.pop() {
            self.slots[index].value = Some(value);
            index
        } else {
            let index = self.slots.len();
            self.slots.push(Slot { generation: 0, value: Some(value) });
            index
        };
        Handle { arena: self.identity, index, generation: self.slots[index].generation }
    }
    fn slot(&self, handle: Handle) -> Option<&Slot<T>> {
        if handle.arena != self.identity { return None; }
        self.slots.get(handle.index).filter(|slot| slot.generation == handle.generation)
    }
    fn get(&self, handle: Handle) -> Option<&T> { self.slot(handle)?.value.as_ref() }
    fn get_mut(&mut self, handle: Handle) -> Option<&mut T> {
        if handle.arena != self.identity { return None; }
        let slot = self.slots.get_mut(handle.index)?;
        if slot.generation != handle.generation { return None; }
        slot.value.as_mut()
    }
    fn remove(&mut self, handle: Handle) -> Option<T> {
        if handle.arena != self.identity { return None; }
        let slot = self.slots.get_mut(handle.index)?;
        if slot.generation != handle.generation { return None; }
        let value = slot.value.take()?;
        if let Some(next) = slot.generation.checked_add(1) {
            slot.generation = next;
            self.free.push(handle.index);
        } // An exhausted generation permanently retires this slot.
        Some(value)
    }
}
fn main() {
    let mut arena = Arena::new().unwrap();
    let old = arena.insert(String::from("draft"));
    assert_eq!(arena.remove(old).as_deref(), Some("draft"));
    let current = arena.insert(String::from("replacement"));
    assert_eq!(old.index, current.index);
    assert_ne!(old.generation, current.generation);
    assert!(arena.get(old).is_none());
    arena.get_mut(current).unwrap().push_str(" page");
    assert_eq!(arena.get(current).map(String::as_str), Some("replacement page"));
    let other: Arena<String> = Arena::new().unwrap();
    assert!(other.get(current).is_none());
    println!("stale handles rejected: ok");
}
#[test]
fn generation_exhaustion_retires_the_slot() {
    let mut arena = Arena::new().unwrap();
    let first = arena.insert("last occupant");
    arena.slots[first.index].generation = u64::MAX; // Test-only boundary fixture.
    let final_handle = Handle { generation: u64::MAX, ..first };
    assert_eq!(arena.remove(final_handle), Some("last occupant"));
    assert!(arena.remove(final_handle).is_none());
    let next = arena.insert("new slot");
    assert_ne!(next.index, final_handle.index);
    assert!(arena.get(final_handle).is_none());
}
#[test]
fn double_remove_does_not_duplicate_a_free_slot() {
    let mut arena = Arena::new().unwrap();
    let old = arena.insert(7);
    assert_eq!(arena.remove(old), Some(7));
    assert_eq!(arena.remove(old), None);
    let a = arena.insert(8);
    let b = arena.insert(9);
    assert_ne!(a.index, b.index);
    assert_eq!(arena.get(a), Some(&8));
    assert_eq!(arena.get(b), Some(&9));
}

use std::{future::Future, pin::Pin, sync::{Arc, atomic::{AtomicBool, Ordering}}, task::{Context, Poll, Wake, Waker}};

#[derive(Default)]
struct Notice(AtomicBool);
impl Wake for Notice {
    fn wake(self: Arc<Self>) { self.0.store(true, Ordering::Release); }
    fn wake_by_ref(self: &Arc<Self>) { self.0.store(true, Ordering::Release); }
}
#[derive(Debug, PartialEq)]
enum Turn<T> { Ready(T), Stalled, BudgetUsed }

// A bounded demonstration driver, not a runtime or an I/O event loop.
fn drive<F: Future>(mut future: Pin<&mut F>, polls: usize) -> Turn<F::Output> {
    let notice = Arc::new(Notice::default());
    let waker = Waker::from(notice.clone());
    let mut cx = Context::from_waker(&waker);
    for _ in 0..polls {
        notice.0.store(false, Ordering::Release);
        match future.as_mut().poll(&mut cx) {
            Poll::Ready(value) => return Turn::Ready(value),
            Poll::Pending if !notice.0.load(Ordering::Acquire) => return Turn::Stalled,
            Poll::Pending => {}
        }
    }
    Turn::BudgetUsed
}
struct Sum { next: u32, limit: u32, total: u64 }
impl Future for Sum {
    type Output = u64;
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<u64> {
        for _ in 0..128 {
            if self.next == self.limit { return Poll::Ready(self.total); }
            self.total += u64::from(self.next);
            self.next += 1;
        }
        if self.next == self.limit { Poll::Ready(self.total) }
        else { cx.waker().wake_by_ref(); Poll::Pending }
    }
}
fn main() {
    let mut sum = std::pin::pin!(Sum { next: 0, limit: 1_000, total: 0 });
    assert_eq!(drive(sum.as_mut(), 1), Turn::BudgetUsed);
    assert_eq!(drive(sum.as_mut(), 16), Turn::Ready(499_500));
    let mut pending = std::pin::pin!(std::future::pending::<()>());
    assert_eq!(drive(pending.as_mut(), 4), Turn::Stalled);
    println!("bounded turns: ok");
}

use std::collections::BTreeMap;
#[derive(Clone, Debug, PartialEq)]
struct Attempt { lesson: String, passed: bool, points: u64 }
#[derive(Default)]
struct Ledger { attempts: BTreeMap<String, Attempt>, score: u64 }
#[derive(Debug, PartialEq)]
enum Record { Added, Duplicate }
#[derive(Debug, PartialEq)]
enum Error { Invalid, Conflict, Full, Overflow }
impl Ledger {
    fn record(&mut self, id: &str, attempt: Attempt) -> Result<Record, Error> {
        if id.is_empty() || id.len() > 128 || attempt.lesson.is_empty()
            || attempt.lesson.len() > 256 || attempt.points > 100
            || (!attempt.passed && attempt.points != 0) { return Err(Error::Invalid); }
        if let Some(previous) = self.attempts.get(id) {
            return if previous == &attempt { Ok(Record::Duplicate) }
                else { Err(Error::Conflict) };
        }
        if self.attempts.len() >= 50_000 { return Err(Error::Full); }
        let next_score = self.score.checked_add(attempt.points).ok_or(Error::Overflow)?;
        self.attempts.insert(id.to_owned(), attempt);
        self.score = next_score;
        Ok(Record::Added)
    }
}
fn main() {
    let mut ledger = Ledger::default();
    let a = Attempt { lesson: "ownership-1".into(), passed: true, points: 20 };
    assert_eq!(ledger.record("attempt-1", a.clone()), Ok(Record::Added));
    assert_eq!(ledger.record("attempt-1", a), Ok(Record::Duplicate));
    assert_eq!(ledger.score, 20);
    let conflict = Attempt { lesson: "ownership-1".into(), passed: true, points: 30 };
    assert_eq!(ledger.record("attempt-1", conflict), Err(Error::Conflict));
    assert_eq!(ledger.score, 20);
    println!("one attempt, one award: ok");
}
